import subprocess, json
def run(args, cwd="/tmp", input=None):
    return subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, cwd=cwd, input=input)
def chart(tree, extra=[], unit="bytes"):
    data=json.dumps({"schema-version":"2024-11-02","pdu":"0.21.1","unit":unit,"tree":tree})
    r=run(["--json-input"]+extra, input=data)
    return r.stdout

# Understand bar rendering: blocks + shading for parent remainder?
# Nested dir1: f1 bar: solid proportional to its size relative to root? 400/1000 * bar_width ; plus ░ for remainder up to parent size (600)
# Let's measure bar widths precisely.
tree2={"name":"root","size":1000,"children":[
 {"name":"dir1","size":600,"children":[{"name":"f1","size":400,"children":[]},{"name":"f2","size":200,"children":[]}]},
 {"name":"dir2","size":400,"children":[{"name":"f3","size":400,"children":[]}]}
]}
for mode in [[], ["--top-down"]]:
    out=chart(tree2, extra=mode)
    for line in out.splitlines():
        # split by │
        parts=line.split("│")
        # parts: [size+tree, bar, percent]
        bar=parts[1] if len(parts)>1 else ""
        print(mode, repr(line), "bar len", len(bar), "solid", bar.count("█"), "shade", bar.count("░"), "space", bar.count(" "))

# Root bar: should be full

# Check percentages rounding: sizes like 1/3
tree={"name":"root","size":3,"children":[{"name":"a","size":1,"children":[]},{"name":"b","size":2,"children":[]}]}
print(chart(tree))
# various percents
for sz in [(1,3),(2,3),(1,6),(5,6),(1,7),(1,8),(1,200),(1,1000),(0,100)]:
    t={"name":"r","size":sz[1],"children":[{"name":"x","size":sz[0],"children":[]}]}
    print(sz, chart(t).splitlines()[0])

# Bar length calculation: total width default? lines len?
out=chart(tree2)
print([len(l) for l in out.splitlines()])
# tree column width and bar width logic: total 150?
# test small tree name lengths
PY"}

