    cand=[i for i,ch in enumerate(line) if ch=="│" and i<be and set(line[i+1:be])<=set("█░▒ ")]
    bs=cand[0]
    bar=line[bs+1:be]
    # count runs
    runs=[]
    for ch in bar:
        if runs and runs[-1][0]==ch: runs[-1]=(ch,runs[-1][1]+1)
        else: runs.append((ch,1))
    return runs, line[:bs], line[be:]

