# make many files if needed
base="/tmp/huge"
if not os.path.exists(base+"/d99"):
    for d in range(100):
        os.makedirs(f"{base}/d{d}", exist_ok=True)
        for f in range(500):
            p=f"{base}/d{d}/f{f}"
            if not os.path.exists(p):
                open(p,"w").write("x"*10)
    print("created")

