    p=subprocess.Popen(["/workspace/executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    err_chunks=[]
    start=time.time()
    # read stderr nonblocking via select
    import fcntl
    fd=p.stderr.fileno(); flags=fcntl.fcntl(fd, fcntl.F_GETFL); fcntl.fcntl(fd, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    out=b""
    while p.poll() is None:
        try:
            d=os.read(fd,4096)
            if d:
                err_chunks.append((time.time()-start, d))
        except BlockingIOError:
            time.sleep(0.02)
        except OSError:
            break
    # drain
    try:
        while True:
            d=os.read(fd,4096)
            if not d: break
            err_chunks.append((time.time()-start,d))
    except: pass
    out=p.stdout.read() if p.stdout else b""
    # stdout pipe may fill block? output is ~100 lines < buffer
    print("args",args,"time",time.time()-start,"stderr chunks",err_chunks[:20],"total stderr len",sum(len(c) for _,c in err_chunks),"stdout len",len(out or b""))
