for args in [["-p","/"],["/"]]:
    p=subprocess.Popen(["/workspace/executable"]+args, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
    fd=p.stderr.fileno(); flags=fcntl.fcntl(fd, fcntl.F_GETFL); fcntl.fcntl(fd, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    chunks=[]; start=time.time()
    while p.poll() is None and time.time()-start<30:
        try:
            d=os.read(fd,65536)
            if d: chunks.append((round(time.time()-start,3), d[:500]))
        except BlockingIOError:
            time.sleep(0.02)
        except OSError: break
    print("args",args,"elapsed",time.time()-start,"poll",p.poll())
    for t,c in chunks[:30]: print(t,c)
    print("total chunks",len(chunks),"total len",sum(len(c) for _,c in chunks))
    if p.poll() is None: p.kill()
    p.wait()
