import subprocess, json
def chart(tree, extra):
    data=json.dumps({"schema-version":"2024-11-02","unit":"bytes","tree":tree}).encode()
    r=subprocess.run(["/workspace/executable","--json-input"]+extra, capture_output=True, input=data)
    return r.stdout.decode(), r.returncode, r.stderr.decode()
# size with 20 digits but <= u64 max: 10000000000000000000 has 20 digits
for sz,name in [(10**19,"abcdefgh"*10),(1,"abcdefgh"*10)]:
    print("sz",sz)
    for w in range(0,45):
        out,code,err=chart({"name":name,"size":sz,"children":[]}, ["-b","plain","-w",str(w)])
        lines=out.splitlines()
        if not lines: print(w,"empty",code,err[:60])
        else:
            l=lines[0]; be=l.rindex("│"); cand=[i for i,ch in enumerate(l) if ch=="│" and i<be and set(l[i+1:be])<=set("█░▒▓ ")]; bs=cand[0]
            print(w, f"prefix={bs} bar={be-bs-1} total={len(l)} code={code} err={err[:60]!r}")
PY"}

