use unicode_width::UnicodeWidthStr as _;

const SCHEMA_VERSION: &str = "2024-11-02";
const VERSION: &str = "0.21.1";

// ---------- panic emulation (old Rust panic report format) ----------
fn backtrace_enabled() -> bool {
    match env::var("RUST_BACKTRACE") {
        Ok(v) => v != "0" && !v.is_empty(),
        Err(_) => false,
    }
}

fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let location = info
            .location()
            .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
            .unwrap_or_else(|| "<unknown>".to_string());
        let message: String = if let Some(s) = info.payload().downcast_ref::<&str>() {
            (*s).to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let thread_name = thread::current().name().unwrap_or("main").to_string();
        eprintln!("\nthread '{}' panicked at {}:\n{}", thread_name, location, message);
        if backtrace_enabled() {
            eprintln!("stack backtrace:");
            eprintln!("note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.");
        } else {
            eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        }
    }));
}

fn fake_panic(location: &str, message: &str) -> ! {
    let _ = io::stdout().flush();
    let _ = io::stderr().flush();
    eprintln!("\nthread 'main' panicked at {}:\n{}", location, message);
    if backtrace_enabled() {
        eprintln!("stack backtrace:");
        eprintln!("note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.");
    } else {
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    }
    let _ = io::stderr().flush();
    process::exit(101);
}

// ---------- CLI value types ----------
#[derive(Clone, Debug, PartialEq, Eq)]
enum BytesFormat {
    Plain,
    Metric,
    Binary,
}
impl ValueEnum for BytesFormat {
    fn value_variants<'a>() -> &'a [Self] {
        &[Self::Plain, Self::Metric, Self::Binary]
    }
    fn to_possible_value(&self) -> Option<PossibleValue> {
        Some(match self {
            Self::Plain => PossibleValue::new("plain").help("Display plain number of bytes without units"),
            Self::Metric => PossibleValue::new("metric")
                .help("Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on"),
            Self::Binary => PossibleValue::new("binary")
                .help("Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on"),
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}
impl ValueEnum for Quantity {
    fn value_variants<'a>() -> &'a [Self] {
        &[Self::ApparentSize, Self::BlockSize, Self::BlockCount]
    }
    fn to_possible_value(&self) -> Option<PossibleValue> {
        Some(match self {
            Self::ApparentSize => PossibleValue::new("apparent-size").help("Measure apparent sizes"),
            Self::BlockSize => {
                PossibleValue::new("block-size").help("Measure block sizes (block-count * 512B)")
            }
            Self::BlockCount => PossibleValue::new("block-count").help("Count numbers of blocks"),
        })
    }
}

#[derive(Clone, Debug)]
enum MaxDepthValue {
    Infinite,
    Finite(std::num::NonZeroU64),
}
fn parse_max_depth(s: &str) -> Result<MaxDepthValue, String> {
    let t = s.trim();
    if t == "inf" {
        Ok(MaxDepthValue::Infinite)
    } else {
        match t.parse::<std::num::NonZeroU64>() {
            Ok(v) => Ok(MaxDepthValue::Finite(v)),
            Err(e) => Err(format!(
                "Value is neither \"inf\" nor a positive integer: {}",
                e
            )),
        }
    }
}

#[derive(Clone, Debug)]
#[allow(dead_code)]
enum ThreadsValue {
    Auto,
    Max,
    Fixed(std::num::NonZeroUsize),
}
fn parse_threads(s: &str) -> Result<ThreadsValue, String> {
    let t = s.trim();
    match t {
        "auto" => Ok(ThreadsValue::Auto),
        "max" => Ok(ThreadsValue::Max),
        _ => match t.parse::<std::num::NonZeroUsize>() {
            Ok(v) => Ok(ThreadsValue::Fixed(v)),
            Err(e) => Err(format!(
                "Value is neither \"auto\", \"max\", nor a number: {}",
                e
            )),
        },
    }
}

fn parse_min_ratio(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
    if v < 0.0 {
        Err("less than 0".to_string())
    } else if v >= 1.0 {
        Err("greater than or equal to 1".to_string())
    } else {
        Ok(v)
    }
}

fn build_cli() -> Command {
    let long_examples = "Examples:\n    Show disk usage chart of current working directory\n    $ pdu\n\n    Show disk usage chart of a single file or directory\n    $ pdu path/to/file/or/directory\n\n    Compare disk usages of multiple files and/or directories\n    $ pdu file.txt dir/\n\n    Show chart in apparent sizes instead of block sizes\n    $ pdu --quantity=apparent-size\n\n    Detect and subtract the sizes of hardlinks from their parent nodes\n    $ pdu --deduplicate-hardlinks\n\n    Show sizes in plain numbers instead of metric units\n    $ pdu --bytes-format=plain\n\n    Show sizes in base 2\u{00b9}\u{2070} units (binary) instead of base 10\u{00b3} units (metric)\n    $ pdu --bytes-format=binary\n\n    Show disk usage chart of all entries regardless of size\n    $ pdu --min-ratio=0\n\n    Only show disk usage chart of entries whose size is at least 5% of total\n    $ pdu --min-ratio=0.05\n\n    Show disk usage data as JSON instead of chart\n    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq\n\n    Visualize existing JSON representation of disk usage data\n    $ pdu --json-input < disk-usage.json";
