#[derive(Clone, Debug)]
struct SchemaVersion;

impl<'de> Deserialize<'de> for SchemaVersion {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        struct SchemaVisitor;
        impl<'de> Visitor<'de> for SchemaVisitor {
            type Value = SchemaVersion;
            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("a string")
            }
            fn visit_str<E>(self, v: &str) -> Result<SchemaVersion, E>
            where
                E: de::Error,
            {
                if v == SCHEMA_VERSION {
                    Ok(SchemaVersion)
                } else {
                    Err(E::custom(format!(
                        "InvalidSchema: {:?}: input schema is not {:?}",
                        v, SCHEMA_VERSION
                    )))
                }
            }
            fn visit_string<E>(self, v: String) -> Result<SchemaVersion, E>
            where
                E: de::Error,
            {
                self.visit_str(&v)
            }
        }
        deserializer.deserialize_string(SchemaVisitor)
    }
}

#[derive(Clone, Debug)]
struct JsonDataInput {
    #[allow(dead_code)]
    schema_version: SchemaVersion,
    #[allow(dead_code)]
    pdu: Option<String>,
    unit: Unit,
    tree: Reflection,
    shared: JsonShared,
}

impl<'de> Deserialize<'de> for JsonDataInput {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        #[derive(Debug)]
        enum Field {
            SchemaVersion,
            Pdu,
            Unit,
            Tree,
            Shared,
            Ignore,
        }
        impl<'de> Deserialize<'de> for Field {
            fn deserialize<D>(deserializer: D) -> Result<Field, D::Error>
            where
                D: Deserializer<'de>,
            {
                struct FieldVisitor;
                impl<'de> Visitor<'de> for FieldVisitor {
                    type Value = Field;
                    fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                        formatter.write_str("field identifier")
                    }
                    fn visit_str<E>(self, value: &str) -> Result<Field, E>
                    where
                        E: de::Error,
                    {
                        Ok(match value {
                            "schema-version" => Field::SchemaVersion,
                            "pdu" => Field::Pdu,
                            "unit" => Field::Unit,
                            "tree" => Field::Tree,
                            "shared" => Field::Shared,
                            _ => Field::Ignore,
                        })
                    }
                    fn visit_string<E>(self, value: String) -> Result<Field, E>
                    where
                        E: de::Error,
                    {
                        self.visit_str(&value)
                    }
                }
                deserializer.deserialize_identifier(FieldVisitor)
            }
        }

        struct JsonDataVisitor;
        impl<'de> Visitor<'de> for JsonDataVisitor {
            type Value = JsonDataInput;
            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                formatter.write_str("struct JsonData")
            }
            fn visit_map<A>(self, mut map: A) -> Result<JsonDataInput, A::Error>
            where
                A: MapAccess<'de>,
            {
                let mut schema_version: Option<SchemaVersion> = None;
                let mut pdu: Option<Option<String>> = None;
                let mut unit: Option<Unit> = None;
                let mut tree: Option<Reflection> = None;
                let mut shared: Option<JsonShared> = None;
                while let Some(key) = map.next_key::<Field>()? {
                    match key {
                        Field::SchemaVersion => {
                            if schema_version.is_some() {
                                return Err(de::Error::duplicate_field("schema-version"));
                            }
                            schema_version = Some(map.next_value()?);
                        }
                        Field::Pdu => {
                            if pdu.is_some() {
                                return Err(de::Error::duplicate_field("pdu"));
                            }
                            pdu = Some(map.next_value()?);
                        }
                        Field::Unit => {
                            if unit.is_some() {
                                return Err(de::Error::duplicate_field("unit"));
                            }
                            unit = Some(map.next_value()?);
                        }
                        Field::Tree => {
                            if tree.is_some() {
                                return Err(de::Error::duplicate_field("tree"));
                            }
                            tree = Some(map.next_value()?);
                        }
                        Field::Shared => {
                            if shared.is_some() {
                                return Err(de::Error::duplicate_field("shared"));
                            }
                            shared = Some(map.next_value()?);
                        }
                        Field::Ignore => {
                            let _ = map.next_value::<IgnoredAny>()?;
                        }
                    }
                }
                Ok(JsonDataInput {
                    schema_version: schema_version
                        .ok_or_else(|| de::Error::missing_field("schema-version"))?,
                    pdu: pdu.unwrap_or(None),
                    unit: unit.ok_or_else(|| de::Error::missing_field("unit"))?,
                    tree: tree.ok_or_else(|| de::Error::missing_field("tree"))?,
                    shared: shared.unwrap_or_default(),
                })
            }
        }

        deserializer.deserialize_map(JsonDataVisitor)
    }
}

