// ---------- panic emulation (old Rust panic report format) ----------
fn backtrace_enabled() -> bool {
    match env::var("RUST_BACKTRACE") {
        Ok(v) => v != "0" && !v.is_empty(),
        Err(_) => false,
    }
}

fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let location = info
            .location()
            .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
            .unwrap_or_else(|| "<unknown>".to_string());
        let message: String = if let Some(s) = info.payload().downcast_ref::<&str>() {
            (*s).to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let thread_name = thread::current().name().unwrap_or("main").to_string();
        eprintln!("\nthread '{}' panicked at {}:\n{}", thread_name, location, message);
        if backtrace_enabled() {
            eprintln!("stack backtrace:");
            eprintln!("note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.");
        } else {
            eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        }
    }));
}

fn fake_panic(location: &str, message: &str) -> ! {
    let _ = io::stdout().flush();
    let _ = io::stderr().flush();
    eprintln!("\nthread 'main' panicked at {}:\n{}", location, message);
    if backtrace_enabled() {
        eprintln!("stack backtrace:");
        eprintln!("note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.");
    } else {
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    }
    let _ = io::stderr().flush();
    process::exit(101);
}

