fn parse_max_depth(s: &str) -> Result<MaxDepthValue, String> {
    let t = s.trim();
    if t == "inf" {
        Ok(MaxDepthValue::Infinite)
    } else {
        match t.parse::<std::num::NonZeroU64>() {
            Ok(v) => Ok(MaxDepthValue::Finite(v)),
            Err(e) => Err(format!(
                "Value is neither \"inf\" nor a positive integer: {}",
                e
            )),
        }
    }
