// ---------- reporter ----------
#[derive(Default)]
struct Counters {
    scanned: u64,
    total: u64,
    erred: u64,
}

struct ReporterShared {
    counters: Mutex<Counters>,
    progress_len: Mutex<Option<usize>>,
    silent: bool,
    progress: bool,
    finished: AtomicBool,
}

struct Reporter {
    shared: Arc<ReporterShared>,
    ticker: Mutex<Option<thread::JoinHandle<()>>>,
}

impl Reporter {
    fn new(silent: bool, progress: bool) -> Arc<Self> {
        let shared = Arc::new(ReporterShared {
            counters: Mutex::new(Counters::default()),
            progress_len: Mutex::new(None),
            silent,
            progress,
            finished: AtomicBool::new(false),
        });
        eprint!("\r");
        let _ = io::stderr().flush();
        let reporter = Arc::new(Reporter {
            shared: shared.clone(),
            ticker: Mutex::new(None),
        });
        if progress {
            let sh = shared.clone();
            let handle = thread::spawn(move || loop {
                thread::sleep(Duration::from_millis(100));
                if sh.finished.load(Ordering::SeqCst) {
                    break;
                }
                print_progress(&sh);
            });
            *reporter.ticker.lock().unwrap() = Some(handle);
        }
        reporter
    }

    fn inc_scanned(&self, size: u64) {
        let mut c = self.shared.counters.lock().unwrap();
        c.scanned = c.scanned.wrapping_add(1);
        c.total = c.total.wrapping_add(size);
    }

    fn report_error(&self, message: &str) {
        {
            let mut c = self.shared.counters.lock().unwrap();
            c.erred = c.erred.wrapping_add(1);
        }
        if self.shared.silent {
            return;
        }
        let mut len_guard = self.shared.progress_len.lock().unwrap();
        if let Some(len) = *len_guard {
            eprint!("\r{}\r", " ".repeat(len));
            eprint!("[error] {}\n\r", message);
            *len_guard = None;
        } else {
            eprint!("\r[error] {}\n\r", message);
        }
        let _ = io::stderr().flush();
    }

    fn finish(&self) {
        self.shared.finished.store(true, Ordering::SeqCst);
        if let Some(handle) = self.ticker.lock().unwrap().take() {
            let _ = handle.join();
        }
        let mut len_guard = self.shared.progress_len.lock().unwrap();
        if let Some(len) = *len_guard {
            eprint!("\r{}\r", " ".repeat(len));
            *len_guard = None;
        } else {
            eprint!("\r");
        }
        let _ = io::stderr().flush();
    }
}

fn print_progress(sh: &Arc<ReporterShared>) {
    let (scanned, total, erred) = {
        let c = sh.counters.lock().unwrap();
        (c.scanned, c.total, c.erred)
    };
    let text = if erred == 0 {
        format!("(scanned {}, total {})", scanned, total)
    } else {
        format!("(scanned {}, total {}, erred {})", scanned, total, erred)
    };
    let mut len_guard = sh.progress_len.lock().unwrap();
    if let Some(len) = *len_guard {
        eprint!("\r{}\r", " ".repeat(len));
    }
    eprint!("\r{}", text);
    *len_guard = Some(text.len());
    let _ = io::stderr().flush();
}

// ---------- filesystem scanner ----------
struct Encounter {
    key: (u64, u64),
    ino: u64,
    size: u64,
    links: u64,
    path: PathBuf,
}

struct Scanner {
    reporter: Arc<Reporter>,
    quantity: Quantity,
    dedupe: bool,
    encounters: Vec<Encounter>,
}

impl Scanner {
    fn measure(&self, md: &fs::Metadata) -> u64 {
        match self.quantity {
            Quantity::ApparentSize => md.len(),
            Quantity::BlockSize => md.blocks().wrapping_mul(512),
            Quantity::BlockCount => md.blocks(),
        }
    }

    fn build(&mut self, path: PathBuf, name: OsString) -> Node {
        let md = match fs::symlink_metadata(&path) {
            Err(e) => {
                self.reporter
                    .report_error(&format!("symlink_metadata {:?}: {}", path, e));
                return Node {
                    name,
                    size: 0,
                    children: Vec::new(),
                    fs_path: Some(path),
                    hardlink_key: None,
                };
            }
            Ok(md) => md,
        };
        let own = self.measure(&md);
        self.reporter.inc_scanned(own);
        let is_dir = md.file_type().is_dir();
        let mut hardlink_key = None;
        if !is_dir && self.dedupe && md.nlink() > 1 {
            let key = (md.dev(), md.ino());
            hardlink_key = Some(key);
            self.encounters.push(Encounter {
                key,
                ino: md.ino(),
                size: own,
                links: md.nlink(),
                path: path.clone(),
            });
        }
        if is_dir {
            let mut children: Vec<Node> = Vec::new();
            let mut sum = own;
            match fs::read_dir(&path) {
                Err(e) => {
                    self.reporter
                        .report_error(&format!("read_dir {:?}: {}", path, e));
                }
                Ok(rd) => {
                    for entry_res in rd {
                        match entry_res {
                            Ok(entry) => {
                                let child_path = entry.path();
                                let child_name = entry.file_name();
                                let child = self.build(child_path, child_name);
                                sum = sum.wrapping_add(child.size);
                                children.push(child);
                            }
                            Err(e) => {
                                self.reporter
                                    .report_error(&format!("read_dir {:?}: {}", path, e));
                            }
                        }
                    }
                }
            }
            Node {
                name,
                size: sum,
                children,
                fs_path: Some(path),
                hardlink_key,
            }
        } else {
            Node {
                name,
                size: own,
                children: Vec::new(),
                fs_path: Some(path),
                hardlink_key,
            }
        }
    }
}

// ---------- hardlink groups ----------
#[derive(Clone)]
struct HardlinkGroup {
    ino: u64,
    #[allow(dead_code)]
    dev: u64,
    size: u64,
    links: u64,
    paths_unique: Vec<PathBuf>,
    raw_detected: usize,
}

fn groups_from_encounters(encounters: &[Encounter]) -> Vec<HardlinkGroup> {
    let mut map: BTreeMap<(u64, u64), HardlinkGroup> = BTreeMap::new();
    for enc in encounters {
        let group = map
            .entry((enc.ino, enc.key.0))
            .or_insert_with(|| HardlinkGroup {
                ino: enc.ino,
                dev: enc.key.0,
                size: enc.size,
                links: enc.links,
                paths_unique: Vec::new(),
                raw_detected: 0,
            });
        group.raw_detected += 1;
        if !group.paths_unique.contains(&enc.path) {
            group.paths_unique.push(enc.path.clone());
        }
    }
    map.into_values().collect()
}

fn compute_summary_from_groups<'a, I>(groups: I) -> Summary
where
    I: Iterator<Item = (u64, u64, usize)>, // (size, links, detected)
{
    let mut summary = Summary::default();
    for (size, links, detected) in groups {
        if detected as u64 > links {
            fake_panic(
                "src/hardlink/hardlink_list/summary.rs:92:21",
                &format!(
                    "Impossible! Total of nlink ({}) is less than detected paths ({}). Something must have gone wrong!",
                    links, detected
                ),
            );
        }
        summary.inodes = summary.inodes.wrapping_add(1);
        summary.all_links = summary.all_links.wrapping_add(links as usize);
        summary.detected_links = summary.detected_links.wrapping_add(detected);
        summary.shared_size = summary.shared_size.wrapping_add(size);
        if detected as u64 == links {
            summary.exclusive_inodes = summary.exclusive_inodes.wrapping_add(1);
            summary.exclusive_links = summary.exclusive_links.wrapping_add(links as usize);
            summary.exclusive_shared_size = summary.exclusive_shared_size.wrapping_add(size);
        }
    }
    summary
}

fn summary_from_encounter_groups(groups: &[HardlinkGroup]) -> Summary {
    compute_summary_from_groups(groups.iter().map(|g| (g.size, g.links, g.raw_detected)))
}

fn summary_from_details(details: &[ReflectionEntry]) -> Summary {
    compute_summary_from_groups(details.iter().map(|d| (d.size, d.links, d.paths.len())))
}

// ---------- tree operations ----------
fn retain_node(
    node: &mut Node,
    depth: u64,
    total: u64,
    max_depth: &MaxDepthValue,
    min_ratio: f64,
) {
    let mut i = 0;
    while i < node.children.len() {
        let child_depth = depth + 1;
        let beyond = match max_depth {
            MaxDepthValue::Infinite => false,
            MaxDepthValue::Finite(m) => child_depth > m.get(),
        };
        let ratio_drop = (node.children[i].size as f64 / total as f64) < min_ratio;
        if beyond || ratio_drop {
            node.children.remove(i);
        } else {
            i += 1;
        }
    }
    for child in &mut node.children {
        retain_node(child, depth + 1, total, max_depth, min_ratio);
    }
}

fn sort_tree(node: &mut Node) {
    node.children.sort_by(|a, b| b.size.cmp(&a.size));
    for child in &mut node.children {
        sort_tree(child);
    }
}

fn dedup_adjust(node: &mut Node) -> HashMap<(u64, u64), (usize, u64)> {
    let original = node.size;
    let mut map: HashMap<(u64, u64), (usize, u64)> = HashMap::new();
    if let Some(key) = node.hardlink_key {
        map.insert(key, (1, original));
    }
    for child in &mut node.children {
        let child_map = dedup_adjust(child);
        for (k, (count, size)) in child_map {
            let entry = map.entry(k).or_insert((0, size));
            entry.0 += count;
        }
    }
    let mut deduction: u64 = 0;
    for (_k, (count, size)) in &map {
        if *count > 1 {
            deduction = deduction.wrapping_add((*count as u64 - 1).wrapping_mul(*size));
        }
    }
    node.size = original.wrapping_sub(deduction);
    map
}

fn zero_duplicate_paths(node: &mut Node, counts: &HashMap<PathBuf, usize>) {
    if node.hardlink_key.is_some() {
        if let Some(p) = &node.fs_path {
            if counts.get(p).copied().unwrap_or(0) > 1 {
                node.size = 0;
            }
        }
    }
    for child in &mut node.children {
        zero_duplicate_paths(child, counts);
    }
}

fn count_fs_paths(node: &Node, counts: &mut HashMap<PathBuf, usize>) {
    if node.hardlink_key.is_some() {
        if let Some(p) = &node.fs_path {
            *counts.entry(p.clone()).or_insert(0) += 1;
        }
    }
    for child in &node.children {
        count_fs_paths(child, counts);
    }
}

fn validate_node(node: &Node, unit: Unit, path: &str) -> Result<(), AppError> {
    for child in &node.children {
        if child.size > node.size {
            return Err(AppError::InvalidInputReflection(format!(
                "ExcessiveChildren: {:?} ({:?}({})) is less than a child named {:?} ({:?}({}))",
                path,
                unit,
                node.size,
                os_display(&child.name),
                unit,
                child.size
            )));
        }
    }
    for child in &node.children {
        let child_path = format!("{}/{}", path, os_display(&child.name));
        validate_node(child, unit, &child_path)?;
    }
    Ok(())
}

fn convert_node(node: &Node) -> ReflectionOut {
    let name = expect_utf8(node.name.clone());
    let children = node.children.iter().map(convert_node).collect();
    ReflectionOut {
        name,
        size: node.size,
        children,
    }
}

fn node_from_reflection(r: Reflection) -> Node {
    Node {
        name: OsString::from(r.name),
        size: r.size,
        children: r.children.into_iter().map(node_from_reflection).collect(),
        fs_path: None,
        hardlink_key: None,
    }
}

// ---------- bytes formatting ----------
fn format_scaled(size: u64, base: u64) -> String {
    if size < base {
        return format!("{}   ", size);
    }
    let suffixes = ["K", "M", "G", "T", "P"];
    let mut exp: usize = 0;
    let mut divisor: u128 = 1;
    while exp < 5 && (size as u128) / divisor >= base as u128 {
        divisor *= base as u128;
        exp += 1;
    }
    let mantissa = (size as f32) / (divisor as f32);
    format!("{:.1}{}", mantissa, suffixes[exp - 1])
}

fn format_size(size: u64, unit: Unit, bytes_format: &BytesFormat) -> String {
    match unit {
        Unit::Blocks => size.to_string(),
        Unit::Bytes => match bytes_format {
            BytesFormat::Plain => size.to_string(),
            BytesFormat::Metric => format_scaled(size, 1000),
            BytesFormat::Binary => format_scaled(size, 1024),
        },
    }
}

// ---------- summary text ----------
fn summary_text(summary: &Summary, unit: Unit, bytes_format: &BytesFormat) -> String {
    if summary.inodes == 0 {
        return "There are no hardlinks.".to_string();
    }
    #[derive(PartialEq)]
    enum Cat {
        All,
        None,
        Some,
    }
    let cat = if summary.exclusive_inodes == summary.inodes {
        Cat::All
    } else if summary.exclusive_inodes == 0 {
        Cat::None
    } else {
        Cat::Some
    };
    let first = match cat {
        Cat::All => "Hardlinks detected! No files have links outside this tree",
        Cat::None => "Hardlinks detected! All hardlinks within this tree have links without",
        Cat::Some => "Hardlinks detected! Some files have links outside this tree",
    };
    let inodes_line = match cat {
        Cat::Some => format!(
            "* Number of shared inodes: {} total, {} exclusive",
            summary.inodes, summary.exclusive_inodes
        ),
        _ => format!("* Number of shared inodes: {}", summary.inodes),
    };
    let links_line = match cat {
        Cat::All => format!("* Total number of links: {}", summary.all_links),
        Cat::None => format!(
            "* Total number of links: {} total, {} detected",
            summary.all_links, summary.detected_links
        ),
        Cat::Some => format!(
            "* Total number of links: {} total, {} detected, {} exclusive",
            summary.all_links, summary.detected_links, summary.exclusive_links
        ),
    };
    let size_line = match cat {
        Cat::Some => format!(
            "* Total shared size: {} total, {} exclusive",
            format_size(summary.shared_size, unit, bytes_format),
            format_size(summary.exclusive_shared_size, unit, bytes_format)
        ),
        _ => format!(
            "* Total shared size: {}",
            format_size(summary.shared_size, unit, bytes_format)
        ),
    };
    format!("{}\n{}\n{}\n{}", first, inodes_line, links_line, size_line)
}

// ---------- visualizer ----------
struct DisplayNode {
    name_final: String,
    size: u64,
    depth: usize,
    children: Vec<DisplayNode>,
    is_last_original: bool,
    is_last_kept: bool,
}

fn build_display(
    node: &Node,
    depth: usize,
    is_last_original: bool,
    tree_cap: usize,
) -> Option<DisplayNode> {
    let name_display = os_display(&node.name);
    let prefix_width = depth * 2 + 3;
    if prefix_width > tree_cap {
        return None;
    }
    let slot = tree_cap - prefix_width;
    let name_width = name_display.width();
    let name_final = if name_width <= slot {
        name_display
    } else if slot >= 4 {
        let new_len = slot - 3;
        if new_len < name_display.len() && !name_display.is_char_boundary(new_len) {
            fake_panic(
                "src/visualizer/tree.rs:131:19",
                "assertion failed: self.is_char_boundary(new_len)",
            );
        }
        let mut truncated = name_display.clone();
        truncated.truncate(new_len);
        truncated.push_str("...");
        truncated
    } else {
        return None;
    };
    let child_count = node.children.len();
    let mut kept: Vec<DisplayNode> = Vec::new();
    for (idx, child) in node.children.iter().enumerate() {
        let is_last_orig = idx + 1 == child_count;
        if let Some(mut child_disp) = build_display(child, depth + 1, is_last_orig, tree_cap) {
            kept.push(child_disp);
            // placeholder, set below
            let _ = &mut child_disp;
        }
    }
    let kept_len = kept.len();
    for (i, child) in kept.iter_mut().enumerate() {
        child.is_last_kept = i + 1 == kept_len;
    }
    Some(DisplayNode {
        name_final,
        size: node.size,
        depth,
        children: kept,
        is_last_original,
        is_last_kept: true,
    })
}

#[derive(Clone)]
struct RowInfo {
    size: u64,
    tree_string: String,
    bar_ancestors: Vec<(u64, usize)>, // nearest first, excludes root
}

fn collect_rows(
    node: &DisplayNode,
    prefix_segments: String,
    bar_ancestors: Vec<(u64, usize)>,
    top_down: bool,
    rows: &mut Vec<RowInfo>,
) {
    let first = if node.depth == 0 {
        if top_down {
            '└'
        } else {
            '┌'
        }
    } else if node.is_last_kept {
        if top_down {
            '└'
        } else {
            '┌'
        }
    } else {
        '├'
    };
    let third = if node.children.is_empty() {
        '─'
    } else if top_down {
        '┬'
    } else {
        '┴'
    };
    let tree_string = format!(
        "{}{}{}{}{}",
        prefix_segments, first, '─', third, node.name_final
    );
    rows.push(RowInfo {
        size: node.size,
        tree_string,
        bar_ancestors: bar_ancestors.clone(),
    });
    let segment_for_node = if node.depth == 0 || node.is_last_original {
        "  "
    } else {
        "│ "
    };
    let child_prefix = format!("{}{}", prefix_segments, segment_for_node);
    let mut child_bar_ancestors: Vec<(u64, usize)> = Vec::new();
    if node.depth >= 1 {
        child_bar_ancestors.push((node.size, node.depth));
    }
    child_bar_ancestors.extend(bar_ancestors.iter().cloned());
    for child in &node.children {
        collect_rows(
            child,
            child_prefix.clone(),
            child_bar_ancestors.clone(),
            top_down,
            rows,
        );
    }
}

fn prop_count(size: u64, total: u64, multiplier: usize) -> usize {
    if multiplier == 0 {
        return 0;
    }
    let wrapped = size.wrapping_mul(multiplier as u64);
    let value = (wrapped as f64 / total as f64).round();
    value as usize
}

fn shade_char(depth: usize) -> char {
    match depth {
        1 => '░',
        2 => '▒',
        _ => '▓',
    }
}

fn make_bar(
    size: u64,
    ancestors: &[(u64, usize)],
    root_size: u64,
    bar_width: usize,
    align_right: bool,
) -> String {
    let mut chars = vec![' '; bar_width];
    let mut prev = prop_count(size, root_size, bar_width);
    let end = prev.min(bar_width);
    for c in chars.iter_mut().take(end) {
        *c = '█';
    }
    for (anc_size, anc_depth) in ancestors {
        let t = prop_count(*anc_size, root_size, bar_width);
        let end = t.min(bar_width);
        if end > prev.min(bar_width) {
            let start = prev.min(bar_width);
            for c in chars.iter_mut().take(end).skip(start) {
                *c = shade_char(*anc_depth);
            }
        }
        if t > prev {
            prev = t;
        }
    }
    if align_right {
        chars.reverse();
    }
    chars.into_iter().collect()
}

fn collect_all_nodes<'a>(node: &'a Node, out: &mut Vec<&'a Node>) {
    out.push(node);
    for child in &node.children {
        collect_all_nodes(child, out);
    }
}

fn render_chart(
    root: &Node,
    unit: Unit,
    bytes_format: &BytesFormat,
    top_down: bool,
    align_right: bool,
    width_spec: WidthSpec,
) -> String {
    // size strings for every node in the input tree (before width pruning)
    let mut all_nodes: Vec<&Node> = Vec::new();
    collect_all_nodes(root, &mut all_nodes);
    let size_strings: HashMap<usize, String> = HashMap::new();
    let _ = size_strings;
    let mut size_width: usize = 0;
    for n in &all_nodes {
        let s = format_size(n.size, unit, bytes_format);
        if s.len() > size_width {
            size_width = s.len();
        }
    }

    let (tree_cap, bar_min, total_opt, fixed_bar): (usize, usize, Option<usize>, Option<usize>) =
        match width_spec {
            WidthSpec::Columns { tree, bar } => (tree, 0, None, Some(bar.max(1))),
            WidthSpec::Total(w) => {
                // empirical distribution of the total width
                let f = size_width + 7;
                let root_name_width = os_display(&root.name).width();
                let root_min_cap = 3 + root_name_width.min(4);
                if w <= f {
                    (f, 3, Some(w), None)
                } else if w <= 17 {
                    (f, 20, Some(w), None)
                } else {
                    let cap_normal = if size_width >= 10 {
                        w
                    } else {
                        w.saturating_sub(17)
                    };
                    if size_width >= 10 {
                        if w < f + 7 {
                            return String::new();
                        }
                    } else if cap_normal < root_min_cap {
                        return String::new();
                    }
                    let bar_min = if size_width >= 10 {
                        1
                    } else if size_width >= 10usize.saturating_sub(9) {
                        1
                    } else {
                        10usize.saturating_sub(size_width).max(1)
                    };
                    (cap_normal, bar_min, Some(w), None)
                }
            }
        };

    let display_root = match build_display(root, 0, true, tree_cap) {
        Some(d) => d,
        None => return String::new(),
    };

    let mut rows: Vec<RowInfo> = Vec::new();
    collect_rows(&display_root, String::new(), Vec::new(), top_down, &mut rows);
    if !top_down {
        rows.reverse();
    }

    let mut tree_width: usize = 0;
    for r in &rows {
        let w = r.tree_string.width();
        if w > tree_width {
            tree_width = w;
        }
    }

    let bar_width: usize = if let Some(fixed) = fixed_bar {
        fixed
    } else {
        let total = total_opt.unwrap_or(0) as i128;
        let remainder = total - (size_width as i128 + 1 + tree_width as i128 + 6);
        if remainder > bar_min as i128 {
            remainder as usize
        } else {
            bar_min
        }
    };

    let root_size = root.size;
    let mut out = String::new();
    for r in &rows {
        let size_s = format_size(r.size, unit, bytes_format);
        let tree_disp_width = r.tree_string.width();
        let pad = tree_width.saturating_sub(tree_disp_width);
        let tree_padded = format!("{}{}", r.tree_string, " ".repeat(pad));
        let bar = make_bar(r.size, &r.bar_ancestors, root_size, bar_width, align_right);
        let percent = prop_count(r.size, root_size, 100);
        out.push_str(&format!(
            "{:>width$} {}│{}│{:>3}%\n",
            size_s,
            tree_padded,
            bar,
            percent,
            width = size_width
        ));
    }
    out
}

// ---------- overlapping arguments ----------
fn remove_overlapping_directory_args(files: &[PathBuf]) -> Vec<PathBuf> {
    let mut canonicals: Vec<Option<PathBuf>> = Vec::new();
    for path in files {
        let is_dir = fs::symlink_metadata(path)
            .map(|md| md.file_type().is_dir())
            .unwrap_or(false);
        let canon = if is_dir {
            fs::canonicalize(path).ok()
        } else {
            None
        };
        canonicals.push(canon);
    }
    let mut keep = Vec::new();
    for i in 0..files.len() {
        let mut drop = false;
        if let Some(ci) = &canonicals[i] {
            for j in 0..files.len() {
                if i == j {
                    continue;
                }
                if let Some(cj) = &canonicals[j] {
                    if cj == ci {
                        if j < i {
                            drop = true;
                        }
                    } else if ci.starts_with(cj) {
                        drop = true;
                    }
                }
            }
        }
        if !drop {
            keep.push(files[i].clone());
        }
    }
    keep
}

// ---------- app ----------
fn unit_from_quantity(q: &Quantity) -> Unit {
    match q {
        Quantity::BlockCount => Unit::Blocks,
        _ => Unit::Bytes,
    }
}

struct CliOptions {
    json_input: bool,
    json_output: bool,
    bytes_format: BytesFormat,
    dedupe: bool,
    top_down: bool,
    align_right: bool,
    quantity: Quantity,
    max_depth: MaxDepthValue,
    min_ratio: f64,
    no_sort: bool,
    silent: bool,
    progress: bool,
    omit_details: bool,
    omit_summary: bool,
    files: Vec<PathBuf>,
    width_spec: WidthSpec,
}

fn run_filesystem(opts: &CliOptions) -> Result<(), AppError> {
    let mut files = opts.files.clone();
    if files.is_empty() {
        files.push(PathBuf::from("."));
    }
    if opts.dedupe {
        files = remove_overlapping_directory_args(&files);
        if files.is_empty() {
            // Should not happen; fall back to original list
            files = opts.files.clone();
            if files.is_empty() {
                files.push(PathBuf::from("."));
            }
        }
    }

    let reporter = Reporter::new(opts.silent, opts.progress);
    let mut scanner = Scanner {
        reporter: reporter.clone(),
        quantity: opts.quantity.clone(),
        dedupe: opts.dedupe,
        encounters: Vec::new(),
    };
    let mut trees: Vec<Node> = Vec::new();
    for path in &files {
        let name = path.as_os_str().to_os_string();
        let tree = scanner.build(path.clone(), name);
        trees.push(tree);
    }
    let encounters = std::mem::take(&mut scanner.encounters);
    reporter.finish();

    let mut root = if trees.len() == 1 {
        trees.into_iter().next().unwrap()
    } else {
        let total = trees
            .iter()
            .fold(0u64, |acc, t| acc.wrapping_add(t.size));
        Node {
            name: OsString::from("(total)"),
            size: total,
            children: trees,
            fs_path: None,
            hardlink_key: None,
        }
    };

    // retain (before dedup / sorting uses original sizes)
    let total_size = root.size;
    retain_node(&mut root, 1, total_size, &opts.max_depth, opts.min_ratio);
    if !opts.no_sort {
        sort_tree(&mut root);
    }

    // hardlink dedup adjustment
    if opts.dedupe {
        dedup_adjust(&mut root);
        let mut counts: HashMap<PathBuf, usize> = HashMap::new();
        count_fs_paths(&root, &mut counts);
        if counts.values().any(|&c| c > 1) {
            zero_duplicate_paths(&mut root, &counts);
        }
    }

    let groups = groups_from_encounters(&encounters);
    let unit = unit_from_quantity(&opts.quantity);

    if opts.json_output {
        let reflection = convert_node(&root);
        let shared = if !opts.dedupe || groups.is_empty() || (opts.omit_details && opts.omit_summary)
        {
            JsonShared::default()
        } else {
            // convert paths (for panic on non-UTF8) before summary when details are shown
            if !opts.omit_details {
                for g in &groups {
                    for p in &g.paths_unique {
                        let _ = expect_utf8(p.as_os_str().to_os_string());
                    }
                }
            }
            let summary = summary_from_encounter_groups(&groups);
            let details = if opts.omit_details {
                None
            } else {
                Some(
                    groups
                        .iter()
                        .map(|g| ReflectionEntry {
                            ino: g.ino,
                            size: g.size,
                            links: g.links,
                            paths: g.paths_unique.iter().cloned().collect(),
                        })
                        .collect(),
                )
            };
            JsonShared {
                details,
                summary: if opts.omit_summary { None } else { Some(summary) },
            }
        };
        let out = JsonDataOut {
            schema_version: SCHEMA_VERSION.to_string(),
            pdu: Some(VERSION.to_string()),
            unit,
            tree: reflection,
            shared,
        };
        let json = serde_json::to_string(&out).unwrap();
        print!("{}", json);
        let _ = io::stdout().flush();
        return Ok(());
    }

    // chart mode
    validate_node(&root, unit, &os_display(&root.name))?;
    let chart = render_chart(
        &root,
        unit,
        &opts.bytes_format,
        opts.top_down,
        opts.align_right,
        opts.width_spec,
    );
    print!("{}", chart);
    let _ = io::stdout().flush();
    if opts.dedupe && !groups.is_empty() {
        let summary = summary_from_encounter_groups(&groups);
        let text = summary_text(&summary, unit, &opts.bytes_format);
        print!("{}\n\n", text);
        let _ = io::stdout().flush();
    }
    Ok(())
}

fn run_json_input(opts: &CliOptions) -> Result<(), AppError> {
    if !opts.files.is_empty() {
        return Err(AppError::JsonInputArgConflict);
    }
    let stdin = io::stdin();
    let mut lock = stdin.lock();
    let data: JsonDataInput = serde_json::from_reader(&mut lock)
        .map_err(AppError::DeserializationFailure)?;
    // drop the lock / reader before proceeding
    drop(lock);

    let unit = data.unit;
    let mut root = node_from_reflection(data.tree);

    validate_node(&root, unit, &os_display(&root.name))?;

    // summary for display: computed before chart rendering
    let summary_opt: Option<Summary> = if let Some(s) = data.shared.summary {
        Some(s)
    } else if let Some(details) = &data.shared.details {
        Some(summary_from_details(details))
    } else {
        None
    };

    if !opts.no_sort {
        sort_tree(&mut root);
    }

    let chart = render_chart(
        &root,
        unit,
        &opts.bytes_format,
        opts.top_down,
        opts.align_right,
        opts.width_spec,
    );
    print!("{}", chart);
    if let Some(summary) = summary_opt {
        let text = summary_text(&summary, unit, &opts.bytes_format);
        print!("{}\n\n", text);
    }
    let _ = io::stdout().flush();
    Ok(())
}

fn main() {
    install_panic_hook();
    let matches = build_cli().get_matches();

    let total_width_opt = matches.get_one::<usize>("total-width").cloned();
    let column_values: Option<Vec<usize>> = matches
        .get_many::<usize>("column-width")
        .map(|v| v.cloned().collect());

    let width_spec = match (&total_width_opt, &column_values) {
        (None, None) => WidthSpec::Total(terminal_width().unwrap_or(150)),
        (Some(w), None) => WidthSpec::Total(*w),
        (None, Some(values)) if values.len() == 2 => WidthSpec::Columns {
            tree: values[0],
            bar: values[1],
        },
        _ => {
            eprintln!("[src/args.rs:191:17] total_width = {:#?}", total_width_opt);
            eprintln!(
                "[src/args.rs:191:17] column_width = {:#?}",
                column_values
            );
            fake_panic("src/args.rs:192:17", "Something goes wrong");
        }
    };

    let opts = CliOptions {
        json_input: matches.get_flag("json-input"),
        json_output: matches.get_flag("json-output"),
        bytes_format: matches
            .get_one::<BytesFormat>("bytes-format")
            .cloned()
            .unwrap_or(BytesFormat::Metric),
        dedupe: matches.get_flag("deduplicate-hardlinks"),
        top_down: matches.get_flag("top-down"),
        align_right: matches.get_flag("align-right"),
        quantity: matches
            .get_one::<Quantity>("quantity")
            .cloned()
            .unwrap_or(Quantity::BlockSize),
        max_depth: matches
            .get_one::<MaxDepthValue>("max-depth")
            .cloned()
            .unwrap_or(MaxDepthValue::Finite(std::num::NonZeroU64::new(10).unwrap())),
        min_ratio: matches.get_one::<f64>("min-ratio").cloned().unwrap_or(0.01),
        no_sort: matches.get_flag("no-sort"),
        silent: matches.get_flag("silent-errors"),
        progress: matches.get_flag("progress"),
        omit_details: matches.get_flag("omit-json-shared-details"),
        omit_summary: matches.get_flag("omit-json-shared-summary"),
        files: matches
            .get_many::<PathBuf>("files")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        width_spec,
    };

    let result = if opts.json_input {
        run_json_input(&opts)
    } else {
        run_filesystem(&opts)
    };

    if let Err(e) = result {
        eprintln!("{}", e);
        process::exit(e.code());
    }
}
