{"command":"cd /workspace && python3 - << 'PY'
import pathlib
p=pathlib.Path("src/main.rs")
t=p.read_text()
old_start=t.index("fn dedup_adjust_by_path(node: &mut Node, groups: &[HardlinkGroup]) {")
