block=t[old_start:old_end]
new="""fn dedup_adjust_by_path(node: &mut Node, groups: &[HardlinkGroup]) {
    // Pre-count, for each hardlink inode, how many scanned paths lie at or
    // below each ancestor path.  This makes the per-node adjustment a lookup.
    let mut counts: HashMap<((u64, u64), PathBuf), usize> = HashMap::new();
    for g in groups {
        for path in &g.paths_all {
            for anc in path.ancestors() {
                *counts
                    .entry(((g.ino, g.dev), anc.to_path_buf()))
                    .or_insert(0) += 1;
            }
        }
    }
    dedup_adjust_recursive(node, groups, &counts);
}

fn dedup_adjust_recursive(
    node: &mut Node,
    groups: &[HardlinkGroup],
    counts: &HashMap<((u64, u64), PathBuf), usize>,
) {
    if !groups.is_empty() {
        let mut deduction: u64 = 0;
        for g in groups {
            let count = match &node.fs_path {
                None => g.raw_detected,
                Some(p) => counts
                    .get(&((g.ino, g.dev), p.clone()))
                    .copied()
                    .unwrap_or(0),
            };
            if count > 1 {
                deduction = deduction.wrapping_add(((count as u64) - 1).wrapping_mul(g.size));
            }
        }
        node.size = node.size.wrapping_sub(deduction);
    }
    for child in &mut node.children {
        dedup_adjust_recursive(child, groups, counts);
    }
}

